#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#define NV 50257
#define ND 768
#define NL 12
#define NH 12
#define HD 64
static float*W; static long N;
void st(long off,int cnt,const char*name){
 double s=0,ss=0,mn=1e9,mx=-1e9;
 for(int i=0;i<cnt;i++){double x=W[off+i];s+=x;ss+=x*x;if(x<mn)mn=x;if(x>mx)mx=x;}
 printf("%-16s off=%-12ld cnt=%-7d mean=%.5f sd=%.5f min=%.5f max=%.5f first=%.5f\n",name,off,cnt,s/cnt,sqrt(ss/cnt-s/cnt*s/cnt),mn,mx,W[off]);
}
void ln(float*o,float*x,float*g,float*b){
 float m=0;for(int i=0;i<ND;i++)m+=x[i];m/=ND;
 float v=0;for(int i=0;i<ND;i++){float d=x[i]-m;v+=d*d;}v/=ND;
 float s=1.0f/sqrtf(v+1e-5f);
 for(int i=0;i<ND;i++)o[i]=(x[i]-m)*s*g[i]+b[i];
}
float gelu(float x){return 0.5f*x*(1.0f+erff(x*0.70710678118654752f));}
int main(){
 FILE*f=fopen("gpt2-124M.ckpt","rb");fseek(f,0,SEEK_END);N=ftell(f)/4;fseek(f,0,SEEK_SET);
 W=malloc(N*4);if(fread(W,4,N,f)!=N)return 1;fclose(f);
 printf("floats=%ld\n",N);
 // name-sorted layout: h0,h1,h10,h11,h2,...,h9, ln_f/b, ln_f/g, wpe, wte
 long wteoff=N-38597376, wpeoff=N-38597376-786432, lnfgoff=N-38597376-786432-768, lnfboff=N-38597376-786432-1536;
 st(wteoff,768,"wte0"); st(wpeoff,768,"wpe0"); st(lnfgoff,768,"ln_f/g"); st(lnfboff,768,"ln_f/b");
 // block offsets in string-sorted order
 long bloffs[12]={0,7087872,14175744,21263616,28351488,35439360,42527232,49615104,56702976,63790848,70878720,77966592};
 int blnum[12]={0,1,10,11,2,3,4,5,6,7,8,9};
 // within-block alphabetical offsets
 long catb=0,catw=2304,cpjb=1771776,cpjw=1772544,ln1b=2362368,ln1g=2363136,ln2b=2363904,ln2g=2364672,cfcb=2365440,cfcw=2368512,cpcb=4727808,cpcw=4728576;
 // find h0 ln1g and ln2g
 long h0=bloffs[0];
 st(h0+ln1g,768,"h0/ln1g"); st(h0+ln2g,768,"h0/ln2g"); st(h0+catb,2304,"h0/catb"); st(h0+catw,16,"h0/catw0");
 // forward pass with token 464 ("The")
 float*wte=W+wteoff,*wpe=W+wpeoff;
 float x[ND],h[ND],q[ND],k[ND],v[ND],att[ND],qkv[2304],h1[3072],tmp[ND];
 for(int i=0;i<ND;i++)x[i]=wte[464*ND+i]+wpe[i];
 for(int li=0;li<NL;li++){
  long b=bloffs[li]; // already in numeric order 0,1,10,11,2,...
  // wait - bloffs is string-sorted, need numeric order
 }
 // actually need to map numeric block -> string-sorted offset
 long nblk[12];
 for(int i=0;i<12;i++)nblk[blnum[i]]=bloffs[i];
 for(int l=0;l<NL;l++){
  long b=nblk[l];
  float*g1=W+b+ln1g,*b1=W+b+ln1b,*cw=W+b+catw,*cb=W+b+catb,*pw=W+b+cpjw,*pb=W+b+cpjb;
  float*g2=W+b+ln2g,*b2=W+b+ln2b,*fw=W+b+cfcw,*fb=W+b+cfcb,*pw2=W+b+cpcw,*pb2=W+b+cpcb;
  ln(h,x,g1,b1);
  for(int j=0;j<2304;j++){float s=cb[j];for(int i=0;i<ND;i++)s+=h[i]*cw[i*2304+j];qkv[j]=s;}
  memcpy(q,qkv,ND*4);memcpy(k,qkv+ND,ND*4);memcpy(v,qkv+2*ND,ND*4);
  for(int hi=0;hi<NH;hi++){
   float sc=0;for(int d=0;d<HD;d++)sc+=q[hi*HD+d]*k[hi*HD+d];sc*=0.125f;
   for(int d=0;d<HD;d++)att[hi*HD+d]=sc*v[hi*HD+d];
  }
  for(int j=0;j<ND;j++){float s=pb[j];for(int i=0;i<ND;i++)s+=att[i]*pw[i*ND+j];tmp[j]=s;}
  for(int i=0;i<ND;i++)x[i]+=tmp[i];
  ln(h,x,g2,b2);
  for(int j=0;j<3072;j++){float s=fb[j];for(int i=0;i<ND;i++)s+=h[i]*fw[i*3072+j];h1[j]=gelu(s);}
  for(int j=0;j<ND;j++){float s=pb2[j];for(int i=0;i<3072;i++)s+=h1[i]*pw2[i*ND+j];tmp[j]=s;}
  for(int i=0;i<ND;i++)x[i]+=tmp[i];
 }
 float*lg=W+lnfgoff,*lb=W+lnfboff;
 ln(tmp,x,lg,lb);
 static float lgs[NV];
 for(int i=0;i<NV;i++){float s=0;for(int j=0;j<ND;j++)s+=tmp[j]*wte[i*ND+j];lgs[i]=s;}
 printf("\nTop 10 predictions for token 464 (The):\n");
 for(int r=0;r<10;r++){int best=0;for(int i=1;i<NV;i++)if(lgs[i]>lgs[best])best=i;printf("#%d token=%d logit=%.4f\n",r,best,lgs[best]);lgs[best]=-1e9;}
 return 0;
}
